// =============================================================================
//  SolarSim - Font.hpp
//  Embedded 5x7 bitmap font (see Font5x7.cpp, generated by scripts/gen_font.py)
// =============================================================================
#pragma once

#include <cstdint>
#include <string>

namespace solsim::render {

extern const std::uint8_t kFont5x7[96][7];

class Framebuffer;
struct Color;
struct Image8;

struct BitmapFont {
    static constexpr int kGlyphW = 5;
    static constexpr int kGlyphH = 7;
    static constexpr int kAdvance = 6; // 1 px spacing

    // Returns the 7 row bitmasks for a character ('?' for unsupported ones).
    static const std::uint8_t* glyph(char c);
    static bool pixel(char c, int col, int row);

    // Width/height in pixels of a single-line string at integer scale.
    static int textWidth(const std::string& s, int scale = 1);
    static int textHeight(int scale = 1) { return kGlyphH * scale; }

    // Draws text (alpha blended, with an optional dark drop shadow).
    // A UTF-8 degree sign (U+00B0) is mapped to glyph 127.
    static void draw(Framebuffer& fb, int x, int y, const std::string& text, const Color& color, int scale = 1,
                     bool shadow = true, float alpha = 1.f);
    // Same, directly on an 8-bit sRGB image (used for overlays after tone mapping).
    static void draw(Image8& img, int x, int y, const std::string& text, std::uint32_t rgb, int scale = 1,
                     bool shadow = true, float alpha = 1.f);
};

} // namespace solsim::render
